inline LocalizedMessage energyAuthorizationFieldMessage(std::string_view language,EnergyAuthorizationFieldMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=energyAuthorizationFieldMessageKeyCount)return {};
    const auto &source=energyAuthorizationFieldLocalePacks()[0];const auto *selected=&source;for(const auto &pack:energyAuthorizationFieldLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
